(function () {
  'use strict';
  var DATA = {"do you often feel bored?":{"blocks":[["A","I rarely feel bored, actually. "],["R","I’m always quite busy – I’ve got my studies, sporting activities and a fairly busy social calendar. "],["E","I’m a very active person and I never seem to have time for all the things I want to do – so I’ve certainly no time to get bored."]]},"what kinds of things would make you feel bored?":{"blocks":[["A","When I feel bored it’s usually when I’m commuting and stuck in traffic. "],["E","I find travelling by car quite frustrating in the big city, and it really affects my mood when there are big traffic jams. "],["S","So, getting stuck in traffic or moving really slowly in traffic makes me feel both frustrated and bored."]]},"what would you do if you feel bored?":{"blocks":[["A","If I feel bored I usually get quite annoyed, and that makes me want to talk to friends to get things off my chest. "],["E","So, usually I will message my friends or give them a call and talk about my feelings, ask them about their day, gossip about daily life… things like this. "],["R","This kind of thing usually relieves my boredom and frustration temporarily."]]},"do you think childhood is boring or adulthood is boring?":{"blocks":[["A","I think both childhood and adulthood can be boring sometimes. "],["E","Childhood is simpler, but in adulthood I can choose more of what I do. "],["S","So I think adulthood is more interesting, even though it also comes with more responsibilities."]]},"do you think it is difficult to remember other people's names?":{"blocks":[["A","Not really. "],["R","I have a really good memory for names and numbers. "],["X","I think some people are forgetful though, like my uncle, always getting my brother and my names mixed up!"]]},"how can you remember other people's names?":{"blocks":[["B","I don’t know – I never have a problem remembering names. "],["A","I associate names with faces. "],["R","I think most of us do this, and that helps us to remember what people are called."]]},"how do you feel if others cannot remember your name?":{"blocks":[["A","I don’t mind. "],["R","I’m not easily offended to be honest. "],["C","Well, unless it’s someone really close to me!"]]},"what makes a good friend?":{"blocks":[["A","A good friend is someone who is fun to be with, who you have some key things in common with, and who understands you. "],["E","A good friend is also someone who is prepared to listen, and also not scared to disagree with you and be direct and honest with you – even when you might not want to hear it."]]},"what do you usually do with your friends?":{"blocks":[["A","I usually hang around in cafes, go shopping a little bit, try new restaurants and bars, and occasionally play sports. Things like this. "],["E","At times I go to the cinema with a friend, or maybe for a long walk in spring or summer."]]},"how do you make friends?":{"blocks":[["B","How do I make friends? … Or, how do people in general make friends? … "],["A","Well, I make friends quite easily. "],["R","I am a very social person and I am not shy, so I seem to meet people quite easily, "],["E","through other friends, through activities on campus… things like this. "],["S","I think most people make friends in the same way."]]},"do you have many friends?":{"blocks":[["A","I have lots of friends. "],["E","I think that, talking of “real friends” I have maybe mainly 3 or 4. But I have lots of other friends… you might call them acquaintances."]]},"are you a good friend to others?":{"blocks":[["A","I think so. "],["C","I mess up sometimes, like all of us do – I can be a bit selfish sometimes, talk about my own problems and concerns above those of others… yes…. "],["S","But in general, I think I’m a good friend to others."]]},"what kinds of advertisements do you watch?":{"blocks":[["B","I detest adverts and I get annoyed when they come on TV or on apps on my phone. "],["E","There are all kinds of adverts and I try to ignore them or skip them if I can. There are adverts for pretty much any product or service you can imagine."]],"note":"这段原参考回答主要表达对广告的态度，没有明确回答“哪些类型”。作答时应先点明广告类型。"},"where can you see advertisements?":{"blocks":[["A","Online, on mobile apps, on websites, on the subway, in elevators. "],["E","There are adverts pretty much everywhere in our lives where we are in commercial places, cities, malls, transport facilities, online, everywhere."]]},"have you ever bought something because of its advertisement?":{"blocks":[["A","I guess I have subconsciously. "],["R","That’s how advertising works, you get presented with ideas when you see adverts and then they affect the decisions you make. "],["X","I recall buying lots of meal deals because of adverts I’ve seen online or in the elevator at work on screens."]]},"do you watch advertisements from the beginning to the end?":{"blocks":[["A","Usually not. "],["E","As I said before, I try to ignore them or skip them. "],["C","But If I’m standing in the elevator going to the 18th floor, and there is nothing else to look at, I find myself watching the adverts on the TV screens there, over and over again, so I guess I do watch some adverts from beginning to end."]]},"do you often see advertisements when you are on your phone or computer?":{"blocks":[["A","Yeah, all the time. "],["E","I see them when I’m watching videos, using social media, or just browsing websites. Sometimes they’re related to things I’ve searched for before, which is a little weird."]]},"is there an advertisement that made an impression on you when you were a child?":{"blocks":[["A","Yeah, I remember seeing a lot of food advertisements on TV when I was little, especially ones for snacks and chocolate. "],["E","They always made the food look so good, and the music was usually really catchy. "],["C","I can’t remember one specific ad, but some of those songs stayed in my head for ages."]]},"do you see a lot of advertising on trains or other transport?":{"blocks":[["A","Yeah, definitely. "],["E","I see quite a lot of ads on the subway, especially on the walls and screens inside the stations. There are also ads on buses and sometimes inside taxis."]]},"do you like advertisements?":{"blocks":[["A","It depends. "],["C","I don’t mind ads if they’re short, funny, or actually useful to me. But I really hate it when an ad suddenly pops up while I’m watching a video, especially if I can’t skip it."]]},"what kind of advertising do you like?":{"blocks":[["A","I like ads that are creative and funny "],["R","because they’re much easier to remember. "],["A","I also enjoy ads with a short story rather than ones that just keep telling you how good a product is. "],["C","And if the music is catchy, I’ll probably pay more attention to it."]]},"do you like shoes?":{"blocks":[["A","I adore them! "],["E","I have dozens of pairs. "],["R","For me, shoes are far more than just something to keep the sole of your foot protected."]]},"do you ever buy shoes online?":{"blocks":[["A","No never. I'll happily buy some things online but never shoes. "],["R","Even though I know my shoe size, different shoes come up differently."]]},"do you prefer comfortable shoes, or good-looking fashionable shoes?":{"blocks":[["A","I think it depends on what I'm doing; you know what kind occasion it is. "],["C","If it's just a normal working (studying) day then I'll opt for something comfortable "],["R","because I don't have to look that good, "],["C","whereas if I'm going out for dinner or some kind of social event I'm more likely to pick something more fashionable and trendy."]]},"what kind of shoes do you like the most?":{"blocks":[["A","I think it's quite important to buy good quality shoes. "],["E","I don't mean expensive luxury brand shoes, just good quality materials, like good leather, well-made shoes. "],["R","If you buy cheap shoes they won't last very long and they'll probably be quite uncomfortable."]],"note":"原参考回答把问题转向鞋的质量；作答时先说清自己最喜欢的鞋类，再补充质量要求。"},"how much money do you usually spend on shoes?":{"blocks":[["A","It really depends on the type of shoes, but I’d say I usually spend a few hundred yuan on a pair. "],["C","If they’re trainers that I’ll wear a lot, I don’t mind paying a bit more. But for everyday shoes, I normally just choose something comfortable and reasonably priced."]]},"do you often send emails?":{"blocks":[["A","Yes, I send emails all the time. "],["R","My university assignments are all submitted via email, and I correspond with my family regularly via email still, although a lot of communication today takes place over wechat, our messaging app in China."]]},"did you receive any handwritten letters when you were a child?":{"blocks":[["A","Yeah, I did. "],["X","I remember my friends and I used to write little letters to each other at school, especially on birthdays or before holidays. "],["E","They weren’t anything serious, but I really enjoyed reading them."]]},"which do you prefer, writing a letter or sending a message?":{"blocks":[["A","I definitely prefer sending a message "],["R","because it’s much quicker and more convenient. "],["E","I can just pick up my phone and text someone whenever I want. "],["C","Handwritten letters do feel more special, but honestly, they take much more time and I rarely have a reason to write one nowadays."]]},"do you prefer to go shopping in the shopping mall or the street market?":{"blocks":[["A","I prefer to shop in street markets, really. "],["C","But it does depend on what I’m buying and how much time I have. "],["R","Street markets are more fun for me, but malls and supermarkets can be more convenient, especially if I’ve got a tight schedule."]]},"are there many street markets in china?":{"blocks":[["A","Yes, there are actually, you know in China in almost every local neighbourhood you can find street markets filled with stalls selling daily produce such as fruit and vegetables, fresh meat and fish and things like that. "],["X","There’s one quite near my home actually. "],["E","They’re really quite popular."]]},"what will you do if you find something lost by others?":{"blocks":[["A","If I find something someone has lost I will likely find a police station and hand it in. "],["E","Or maybe ask around the local shops and places in the area."]]},"have you ever lost anything?":{"blocks":[["A","I rarely lose things. "],["C","But I did lose my phone once, after a party with friends. "],["E","I was really stressed about it."]]},"will you post on social media if you lose your items?":{"blocks":[["A","It depends what the item is. "],["C","I will certainly post a note on social media if I was in a certain venue and I think there is a chance that someone else there might have found it. If I lose something randomly in the city, then no I probably won’t."]]},"do you collect anything?":{"blocks":[["A","I don’t collect anything really. "],["C","I used to collect small plastic figurines when I was a kid – characters from cartoons I watched, in fact. "],["S","But now, I can’t think of anything I collect… nothing really."]]},"are there any things you keep from childhood?":{"blocks":[["A","I don’t keep much from my childhood to be honest. "],["R","We have moved house so many times, and always to fairly small flats, that I never really managed to keep or collect much. "],["E","I have some old family photos and some books – that’s about it."]]},"where do you usually keep things you collect?":{"blocks":[["A","Well… I don’t actually collect anything, but if I were to collect things, I’d keep them in my room. "],["X","That’s what my sister does with her collection of soft toys she keeps them in her room some on her bed, carefully arranged, and some in the wardrobe."]]},"in what conditions would you use a computer?":{"blocks":[["A","I usually use a computer for work. "],["C","I used to use a computer for playing games and reading the news, too, but now I do these things on my phone and tablet – "],["S","so, yes, I only use my computer for work really."]]},"when was the first time you used a computer?":{"blocks":[["A","I first used a computer when I was in middle school. "],["E","A friend of mine invited me round to his house and his father had one. I can’t remember what type it was now, but it had some fun games."]]},"in what conditions would it be difficult for you to use a computer?":{"blocks":[["A","It would be hard for me to use a computer while on public transport, or in my grandmother’s house in the countryside. "],["R","You see, I work online mainly, and the internet is terrible in her village."]]},"is growing vegetables popular in your country?":{"blocks":[["A","It's getting more popular, especially since lockdown. "],["R","Loads of people got into it when they had nothing else to do! "],["X","Allotments have massive waiting lists now - my mate's been waiting two years for one."]]},"do many people grow vegetables in your city?":{"blocks":[["A","Not as many as you'd think, being London and all. "],["R","Most of us live in flats with no gardens. "],["C","But there are community gardens popping up everywhere, and some people guerrilla garden on roundabouts!"]]},"do you think it's easy to grow vegetables?":{"blocks":[["A","Depends what you're growing really. "],["X","Herbs and salad leaves are dead easy - even I can manage those! "],["C","But proper veg like carrots or courgettes?"]],"note":"原参考回答最后提出了反问，但没有继续说明种植其他蔬菜的难度。练习时把这个区别说完整。"},"should schools teach students how to grow vegetables?":{"blocks":[["A","Absolutely! "],["R","It's brilliant for kids - gets them outside, teaches them where food comes from. "],["X","My nephew's primary school has a little vegetable patch and he loves it."]]},"are you interested in growing vegetables and fruits?":{"blocks":[["A","Yeah, I'd love to but I'm rubbish at it! "],["X","Tried growing tomatoes on my windowsill last summer - they all died within weeks. "],["C","My nan's brilliant at it though, her garden's like a proper allotment."]]},"how did you learn to be polite as a child?":{"blocks":[["A","Mostly from my parents and teachers, I think. "],["E","They always reminded me to say things like “please” and “thank you” and to greet people properly. And, you know, after hearing that again and again, it just became a habit for me."]]},"do you think being polite is very important?":{"blocks":[["A","Yes, definitely. "],["R","I think basic manners can make everyday communication much easier. "],["X","Even small things, like saying thank you or listening when someone is talking, can make people feel respected."]]},"what kind of person do you think is polite?":{"blocks":[["A","I think a polite person is someone who's considerate of others — like holding the door open, not interrupting, saying please and thank you. "],["E","But more than just manners, I think it's about genuinely making people around you feel respected and comfortable. "],["S","That's what real politeness is, I think."]]},"have you met someone who is polite recently?":{"blocks":[["A","Yeah, actually! "],["X","There was a guy on the subway last week who gave up his seat for an elderly passenger without hesitating. "],["E","It was such a small thing but it really stood out."]]},"when should people show respect to others?":{"blocks":[["A","I think people should show respect to others all the time, not only in formal situations. "],["X","For example, we should listen when someone is speaking, avoid interrupting them and respect different opinions, even if we don’t agree. "],["C","It’s especially important when talking to older people, teachers or colleagues, but respect should really go both ways."]]},"do you think your city is clean?":{"blocks":[["A","Yeah, I think so. "],["E","The streets are usually quite clean, especially in the city centre, and there are cleaners working every day. "],["C","Of course, you can still see some rubbish here and there, but overall, I’d say the environment is pretty well kept."]]},"would people just throw rubbish on the street?":{"blocks":[["A","Most people wouldn’t, "],["R","because there are usually rubbish bins nearby. "],["C","But, you know, there are still a few people who do it, especially with small things like tissues or food wrappers. "],["S","However, I think it’s less common now than it used to be."]]},"how do you feel when you see someone throw rubbish on the street?":{"blocks":[["A","I’d feel a bit annoyed, to be honest. "],["R","It just looks really careless, especially when there’s a rubbish bin only a few steps away. "],["E","I probably wouldn’t say anything to them, but I’d definitely think they should be more responsible."]]},"do you think it's easy to teach people not to throw rubbish around?":{"blocks":[["A","I think it depends. "],["C","For children, it’s probably quite easy if they learn this habit from a young age. But for adults who have been doing it for years, it can be harder."]]},"what do you do with garbage when you are on the street?":{"blocks":[["A","I usually look for a rubbish bin and throw it away there. "],["C","If I can’t find one, I’ll just keep it in my bag or hold onto it until I see one. "],["E","I don’t think carrying a small piece of rubbish for a while is a big deal."]]},"how important do you think it is to keep the city clean?":{"blocks":[["A","I think it’s really important "],["R","because a clean city is just much nicer to live in. It also gives visitors a better impression. And if rubbish is left everywhere, it can smell bad and make public places uncomfortable, so everyone should do their part."]]},"how do you recycle things like paper and plastic?":{"blocks":[["A","Well, I usually separate them from normal rubbish and put them into recycling bins if there are any nearby. "],["E","At home, I also keep things like cardboard boxes and plastic bottles separately. It’s quite a simple habit, but I think it can still make a difference."]]},"what things make you tired?":{"blocks":[["A","Lots of things make me feel tired these days. "],["C","It also depends on the time of year, to be honest. "],["X","I get more tired in the summer."]]},"what do you do when you feel tired?":{"blocks":[["A","Well, when I feel tired, if I have the opportunity, then I will try to take a rest, but it's not always so simple. "],["C","We cannot always take a rest when we feel tired. "],["E","Sometimes we just have to keep going until we have the chance to go to sleep."]]},"who do you prefer to talk to when you feel tired, your friends or family members?":{"blocks":[["A","When I'm tired I prefer to just be on my own, but if I have to talk to anyone I prefer it to be my friends. "],["R","Sometimes my family members are a bit pushy, they talk about my work future or about when I might find a boyfriend and think about marriage and stuff like this. "],["S","So, if I am really tired I try not to speak much to my family really."]]},"do you want to talk to strangers when you feel mentally tired?":{"blocks":[["A","No, to be honest, I find talking to strangers quite an effort. "],["C","If I'm really awake and in a very social mood then I don't mind talking to strangers and I think I am quite good with people, but if I'm really tired mentally, I don't really want to engage in small talk or make an effort to really connect with people. "],["S","I think that's best done when you've got a lot of energy or in a positive social environment not when you are really really tired."]]},"do you often feel tired?":{"blocks":[["A","Yes, quite often, especially when I have a lot of classes or assignments to deal with. "],["E","And after a day like that, I’m literally stressed out and just want to lie down, watch something relaxing, and go to bed a bit earlier."]]},"do you prefer sitting by the window when you travel?":{"blocks":[["A","Yes, definitely. I really like sitting by the window, especially on trains or planes. "],["R","I enjoy looking outside and watching the scenery change."]]},"did you ever go on a long journey with your family when you were a child?":{"blocks":[["A","Yes, I did. "],["X","When I was a child, my family sometimes took long road trips during holidays. "],["E","I remember sitting in the back seat, listening to music and looking out of the window."]]},"what do you usually do during a long journey?":{"blocks":[["A","Well, I usually listen to music or watch something on my phone, especially if the journey is several hours long. "],["E","Sometimes I also sleep for a while "],["R","because long trips can be quite tiring. "],["C","If I’m travelling with friends, we’ll probably chat, play some games, or just look out of the window together."]]},"do you prefer travelling alone or with other people?":{"blocks":[["A","I definitely prefer travelling with other people, especially my friends. "],["R","I think the journey feels much shorter when you have someone to talk to, and it’s also more fun to share the experience with someone else. "],["C","Travelling alone can be peaceful sometimes, but if the trip is really long, I’d probably get bored quite quickly."]]},"what is the longest journey you have ever taken?":{"blocks":[["A","The longest journey I’ve ever taken was probably a long-haul flight between China and the UK. "],["E","It took many hours, and honestly, I felt pretty exhausted by the end of it. I mostly watched films, listened to music and tried to sleep."]]},"have you made any crafts with paper?":{"blocks":[["A","Yeah, I have. "],["X","I used to make simple paper crafts at school, like paper flowers and little animals. "],["E","I wasn’t particularly good at it, but I found it quite fun, especially when I did it with my classmates."]]},"do you still write handwritten letters?":{"blocks":[["A","Not really. "],["E","I usually just text people "],["R","because it’s much quicker and more convenient. "],["E","I can’t even remember the last time I wrote a proper letter by hand."]]},"do people still keep handwritten letters today?":{"blocks":[["A","Yeah, I think some people do, especially if the letter is from someone important to them. "],["R","Handwritten letters feel much more personal than text messages, so people might keep them as memories. "],["C","But I don’t think it’s as common as it used to be, "],["R","since most people communicate online now."]]},"do you carry paper and pens with you when you go out?":{"blocks":[["A","I usually carry a pen in my bag, but I don’t really bring paper with me. "],["E","If I need to write something down, I normally just use the notes app on my phone. "],["C","But having a pen is still useful "],["R","because sometimes I need one to fill in a form or sign something."]]},"what did you like to do with paper as a child?":{"blocks":[["A","Well, I really liked drawing when I was little, so I used to spend a lot of time drawing random things on paper. "],["E","I also enjoyed folding paper into simple things like planes or animals. "],["R","It was a really easy way to keep myself busy, especially when I was bored."]]},"do you remember your first day at secondary school?":{"blocks":[["A","Yeah, I do, although I can’t remember every detail. "],["E","I was pretty nervous "],["R","because everything was new, and I didn’t know many people in my class. "],["E","But after talking to my classmates and making a few new friends, I started to feel much more comfortable."]]},"were there any subjects that you found difficult at secondary school?":{"blocks":[["A","Yeah, definitely. I found physics quite difficult "],["R","because there were so many formulas to remember, and sometimes I just couldn’t understand how to use them. "],["E","I had to spend much more time on physics than on my other subjects, so it was probably the most challenging one for me."]]},"what was your favourite subject at secondary school?":{"blocks":[["A","My favourite subject was definitely English. "],["R","I really enjoyed learning new words and watching English videos in class, and I was also pretty good at it. "],["S","So compared with subjects like maths or physics, English classes were much more relaxing and enjoyable for me."]]},"is there anything you miss about your secondary school?":{"blocks":[["A","Yeah, I really miss spending time with my friends every day. "],["E","We used to have lunch together, chat during breaks, and sometimes hang out after school. "],["R","Now everyone is busy with their own lives, so it’s much harder for us to see each other as often as we used to."]]},"are you looking forward to working?":{"blocks":[["A","I have been wanting to work full time, that’s for sure. "],["E","I can now imagine myself waking up early in the morning, getting my business attire on and sitting behind my office desk. I wonder how it feels to work with other professionals and with the boss always around… It could be stressful but interesting, I guess."]]},"do you like your subject? (why? / why not?)":{"blocks":[["A","Honestly, I don’t. "],["B","I am halfway through my college career. "],["R","But reality struck me when the material we learned in class was much more difficult and the assignments weren’t fun."]]},"do you prefer to study in the mornings or in the afternoons?":{"blocks":[["A","I am not a morning person, I’m afraid. "],["C","But to be honest, studying in the afternoon is even worse. "],["R","I get really sleepy from one to four in the afternoon."]]},"do you think it is important to choose a subject you like?":{"blocks":[["A","Definitely! "],["R","I think interest is the best motivator, if I choose something I’m keen on, I will be willing to sacrifice my leisure time because it is a worthwhile sacrifice to me. "],["E","In addition, when I face some difficulties, I will do my best to overcome the problems."]]},"do you work or are you a student?":{"blocks":[["A","I’m a student at Tsinghua University in Beijing. I’m a student, and I’m a freshman in Tsinghua University. I’m a student, a high school student."]],"note":"这里是三种身份的备选回答，请按真实身份选一句，不要把三种身份连在一起说。"},"is your subject interesting to you?":{"blocks":[["A","Absolutely. I find computer science really stimulating. "],["X","Imagine creating something useful just using codes and numbers."]]},"what are the most popular subjects in china?":{"blocks":[["A","It’s hard to say nowadays. "],["E","You know, due to the globalization, our country is much more developed than ever. Every subject has something to offer to the society."]],"note":"这段原参考回答没有列出具体学科。练习时先点明一两门受欢迎的学科。"},"what would you like to do in the future?":{"blocks":[["A","I would love to be a teacher. "],["R","Most of the women in my family are teachers, they have a huge impact on my life. I think it is wonderful to get to change people’s lives by what I say or do on the stage."]]},"why did you choose to study that subject?":{"blocks":[["R","I chose math because I liked it in high school. I was always strong in math and science, so it seemed like a natural progression. Also, I did some research on career opportunities, and it seemed to be a subject with a promising future."]]},"is there any kind of technology you can use in study?":{"blocks":[["A","For studying I use a computer and my phone. "],["E","I often download research papers and read them on my phone and make notes onto the notes section of my phone too. I use my computer to actually write essays and do other homework tasks."]]},"what kind of learning method helps you?":{"blocks":[["A","Well.. I am not so familiar with different learning methods, but off the top of my head, I'd say that collaborative project work in groups with classmates is something that I really benefit from – more so than sitting at individual desks reciting stuff, anyway."]],"note":"开头的 Well 是停顿语，重点是后面完整回答的学习方法。"},"how many hours a week do you study for?":{"blocks":[["A","I probably study alone, after university, for maybe around 15 hours a week, but it depends on the time of year. "],["C","Closer to exams, I study more, during the summer, I study a lot less!"]]},"where is your school?":{"blocks":[["A","My school is located in the heart of Beijing, the capital of China. "],["E","It's situated in a bustling area with convenient transportation, surrounded by many shops, restaurants and recreational facilities. The location is ideal for students as it provides easy access to various resources and opportunities in the city."]]},"do you like your school?":{"blocks":[["A","Absolutely! I'm really fond of my school. "],["R","It has top-notch facilities, a beautiful campus environment, and most importantly, a strong academic atmosphere."]]},"is there anything you want to change about your school?":{"blocks":[["A","While I'm quite satisfied with my school overall, there is one aspect I would like to see improved, which is the limited space in some classrooms. "],["E","During peak hours, it can get a bit crowded and stuffy. If the school could expand some of the classrooms or better utilize the existing space, it would create a more comfortable learning environment for students."]]},"do you think your school is a good place to study?":{"blocks":[["A","Yes, I believe my school is an excellent place to study. "],["R","It offers a supportive learning environment, well-qualified teachers, and a wide range of resources that cater to diverse learning styles. Additionally, the emphasis on both academic and personal development prepares students effectively for future challenges."]]},"what is the environment like at your school?":{"blocks":[["A","The environment at my school is very supportive and encouraging. "],["E","Students are motivated by both peers and teachers to strive for excellence while being provided with the guidance needed to reach their potential."]]},"how important is interest in study?":{"blocks":[["A","Interest in study is essential "],["R","as it directly influences motivation and engagement. "],["E","A genuine interest in what one is studying can lead to deeper understanding, increased productivity, and overall better academic results."]]},"which subject do you find challenging?":{"blocks":[["A","I find Physics quite challenging, "],["R","primarily due to its complex concepts and theories that require a strong grasp of both mathematics and abstract reasoning. "],["C","However, overcoming these challenges is incredibly rewarding."]]},"do you like your job?":{"blocks":[["A","Definitely! "],["R","I enjoy the variety and special projects where I can take ownership of the final product. "],["S","My job provides me with both, so yes, it is a good job and I find it very rewarding."]]},"do you miss being a student?":{"blocks":[["A","I definitely do! "],["E","Sometimes I just wonder what would have happened if I had studied harder when I was in university. "],["R","I just miss the days when I had nothing to worry about but the exams."]]},"what work do you do?":{"blocks":[["A","I am a teacher at a high school. "],["B","I started there in Jan 2015 after graduating from college. "],["E","I would say it is a pretty challenging job."]]},"why did you choose to do that type of work (or that job)?":{"blocks":[["R","Teaching is my passion. "],["E","I don’t view my career as a “job” per say. I see it more as my calling in life."]],"note":"题目直接问“为什么”，因此这段可以从理由开始，不必再凑一个观点句。"},"is there any kind of technology you use at work?":{"blocks":[["A","I use mainly a laptop computer and my phone at work. "],["E","Sometimes I also use a photocopier scanner, and a video camera if I’m making short promotional videos with my company. "],["S","But mainly, I just use a computer."]]},"can you manage your time well when you work?":{"blocks":[["A","Yes, I am a project manager in my office, so I am quite good at managing my time and the other people's time on the team. "],["E","I've worked as an IT manager for several years now."]]},"how many hours a week do you work for?":{"blocks":[["A","I work for about 40 hours a week at least that is what my contract stipulates, but in reality I would say that I work almost 60 hours a week "],["R","because I do a lot of extra stuff for my team, and end up taking on more projects outside of my normal scope of work pretty often, actually."]]},"do you currently have a good work environment?":{"blocks":[["A","Yes, I'm fortunate to have a very supportive work environment. "],["E","It is collaborative and encourages open communication, which I find essential for personal and professional growth. The management also prioritizes employee well-being, which enhances productivity and overall job satisfaction."]]},"what do you think could be improved at your workplace?":{"blocks":[["A","One area for improvement could be enhancing the flexibility of work hours and remote work options. "],["R","Increasing flexibility could help accommodate the diverse needs of all employees, leading to improved work-life balance."]]},"have you ever thought about changing jobs?":{"blocks":[["A","While I am generally satisfied with my current position, I have considered changing jobs to seek new challenges and opportunities for professional growth. "],["R","Exploring different roles and industries can provide valuable experiences and broaden my skill set."]]},"what do you think would be challenging when you start working in the future?":{"blocks":[["A","Adapting to the rapid pace of technological change in the workplace will likely be a challenge. "],["R","Keeping up with new tools, systems, and industry standards will require continuous learning and adaptability."]]},"is there a place in your company that makes you feel relaxed?":{"blocks":[["A","Yes, we have a quiet lounge area that is filled with plants and comfortable seating. "],["R","It's a great spot to take a break and recharge, away from the usual hustle and bustle of the office environment."]]},"what are the advantages of a company having a relaxation room?":{"blocks":[["A","A relaxation room in a company can significantly boost employee morale and productivity. "],["E","It provides a space for employees to unwind and destress, which is crucial for maintaining mental health. "],["R","Additionally, such spaces can enhance creativity, as taking breaks in a relaxed setting allows employees to return to their tasks with a fresh perspective and renewed energy."]]},"for you, what benefits are there living in a big city?":{"blocks":[["A","Well, first of all, there are a great number of opportunities for both education and job-hunting in big cities, which explains why people from small cities, towns and villages are flooding to big cities nowadays. "],["E","Plus, the fact that cities offer more modern facilities and conveniences makes them even more attractive to people."]]},"has your hometown changed much in recent years?":{"blocks":[["A","Absolutely! "],["X","Take traffic as an example, the most common transport facility used to be buses, it could be really crowded sometimes "],["R","since people didn’t have any other options. "],["C","However, today, BRT and subway systems have made people’s lives easier than ever."]]},"how long have you been living here?":{"blocks":[["A","For about half my life, so that is about 10 years. "],["B","I went to school here, and now I’m working in the same city. "],["E","In fact, time has gone by really quickly "],["R","because there’s so much to do here and I’ve been so active."]]},"is that a big or a small place?":{"blocks":[["A","This city is so huge. "],["E","I often get lost here. "],["X","Like the other day, I travelled to a new neighborhood that had this restaurant people were raving about."]]},"what do you like most about your hometown?":{"blocks":[["A","What I love the most about it is the mystery. "],["E","I mean there are so many places inside this city that I have yet to explore. "],["X","I could spend years checking out every restaurant and attraction Beijing has to offer."]]},"where in your country do you live?":{"blocks":[["A","I live in Beijing. "],["E","However, "],["R","since the city is so big, it would take hours to even scratch the surface, "],["E","but to sum it up, Beijing is the political and cultural heart, and one of the major economic centers of the world today."]]},"do you know any famous people in your area?":{"blocks":[["A","In my district of my city, I don’t know any famous people. "],["R","I think famous people tend to live away from the crowds in China, in places where they will be left alone and not bothered by people or the press."]]},"do you like the area that you live in?":{"blocks":[["A","Yes, I like the area where I live. "],["R","Since I have lived there for a long time it makes me feel comfortable. "],["X","There is a saying: “Home is where the heart is”."]]},"how has your area changed in recent years?":{"blocks":[["A","Some positives changes are that the pollution is getting better. "],["C","It was a lot worse a few years ago. "],["R","Recently, the government has made some changes to the factories nearby you see."]]},"where do you like to go in that area?":{"blocks":[["A","I like to go shopping and hang out with my friends. "],["E","When the weather is nice, I like to go to the park and enjoy the nature. "],["R","It makes me feel refreshed."]]},"do you think the area you live in now is suitable for people of all ages?":{"blocks":[["A","Yes, most certainly. "],["R","I think that I am very lucky to be living in a very central area of my city, close to great public transport facilities, and quite a few entertainment and leisure options too. "],["X","There are a few malls nearby, with fantastic restaurants in, lots of shops, a gym, which I go to every day almost, a swimming centre which I attend with my family on weekends, and there's quite a few nice parks within a short walking distance too."]]},"are people in your area friendly?":{"blocks":[["A","I wouldn't say people in my area are especially friendly, or unfriendly, really. "],["C","They are alright, I suppose. "],["X","I thought they were relatively friendly, before I went to Spain on holiday and found how friendly and happy people seemed to be in service interactions, in the streets, on public transport, and so on, there in Spain."]]},"are the transport facilities in your place very good?":{"blocks":[["A","Honestly, I wish they were better. "],["R","I have to walk 20 minutes to the bus stop, and the subway takes another 30 minutes when I get to work. "],["E","My dream home is a house located right next to a bus stop or subway terminal."]]},"do you live alone or with your family?":{"blocks":[["A","I’m a student at the moment, and I live with my parents. "],["E","Actually I quite like it, "],["R","because my mother is the best cook that I know - it’s always wonderful to have a tasty meal after a day of school work. "],["E","We also talk about our days with each other while we’re enjoying dinner, it just feels good."]]},"do you live in a house or a flat?":{"blocks":[["A","I live in a flat, and my flat is situated in a quiet little neighborhood on the north side of the city. "],["B","My parents first moved there in 2000 when they wanted to start a new life and raise a family."]]},"do you plan to live here for a long time?":{"blocks":[["A","Not really! "],["R","I want to blaze my own trail and live in a place that forces me to reach out and meet new people. "],["E","I was thinking about moving to Shanghai for a few days to gain a bit more cultural experience of the world."]]},"how long have you lived there?":{"blocks":[["A","I’ve lived there for three years and I really love my place. "],["R","Since it’s on the 11th floor, it’s well ventilated and there is plenty of sunshine. "],["E","I love to sink into the soft sofa to watch TV and eat snacks."]]},"what can you see when you look out the window of your room?":{"blocks":[["A","I can see the whole community from my window. "],["E","In the morning, people are going to school or work, everyone is in a hurry. "],["C","However, in the evening, it is not that fast-paced anymore."]]},"what do you usually do in your house/flat/room?":{"blocks":[["A","At weekends, I spend most of my time studying and sleeping in my room. "],["C","On weekdays, I spend time in the kitchen, baking some cakes or sweet stuff for my mother. "],["E","Sometimes, we watch films in the living room."]]},"which is your favorite room in your home?":{"blocks":[["A","I think it must be my bedroom. "],["E","My bedroom is not that big but quite neat. There are some posters of Kobe Bryant on the wall "],["R","because he is my favorite basketball player."]]},"which room does your family spend most of the time in?":{"blocks":[["A","My family loves to stay in the living room "],["R","as this is the only place in the flat where we can do a lot of things together. "],["E","We play board games, watch films and TV programs. We play cards sometimes and we spend time working on huge puzzles together."]]},"would you be willing to live in the countryside in the future?":{"blocks":[["A","In the future, probably. "],["R","There is a peacefulness I enjoy when visiting the countryside. People there are friendly and always willing to start a conversation."]]},"have you ever been to a history museum?":{"blocks":[["A","Yes, I’ve been to several history museums. "],["E","Some of them I’ve found really boring, and some I’ve found really interesting – it depends how the artefacts are exhibited. I tend to prefer natural history museums that house dinosaur skeletons and interactive experiences."]]},"do you like history?":{"blocks":[["A","I enjoy learning about aspects of history yes. "],["C","I don’t really like studying history in school – "],["R","it’s usually boring and full of dates and events that I don’t find that very interesting. "],["C","But I do enjoy learning about certain aspects of history – like how different inventions came about, or how we evolved from apes and came to live in caves, or how the pyramids might have been built and why."]]},"have you ever watched historical films?":{"blocks":[["A","I have seen a few history documentaries, yes. "],["E","In terms of actual films, movies, I’ve seen a few historical films, and some of them I enjoy, and some I don’t like very much. "],["S","It really depends."]]},"did you like history when you were young?":{"blocks":[["A","I didn’t really. "],["C","I liked certain fun facts, like I said earlier, like how the pyramids were built or about how dinosaurs lived and how they became extinct. But history lessons in school and the usual sort of national and political history I find uninteresting and uninspiring."]]},"when was the last time you read about history?":{"blocks":[["A","The last time I read about something in history was a book I had about tribes in Africa. "],["E","It is fairly interesting actually. I quite like reading about how they hunted animals in hundreds of years ago, and how certain tribes got along well, and got along badly with others, and things like this."]]},"do you use headphones?":{"blocks":[["A","I use headphones a lot. "],["R","In fact, I really enjoy the sound of music on headphones. "],["E","Today the quality is really good, and headphones have improved a lot in recent years and are more comfortable too."]]},"when do you use headphones?":{"blocks":[["A","I usually wear headphones when I am commuting to work, when I am in bed at night and want to listen to podcasts or some of the my favourite music before sleep. "],["E","I also use headphones when I am chatting on the phone sometimes."]]},"what type of headphones do you use?":{"blocks":[["A","I use the standard headphones that came with the my mobile phone. "],["E","They’re pretty good quality. "],["C","I know some people buy really special expensive headphones, but mine are a normal brand and I think they’re really good."]]},"in what occasions will you not use headphones?":{"blocks":[["A","I don’t use headphones when I’m hanging out with friends, or when I’m at work. "],["R","I think that’s a bit rude. "],["S","Usually I only use headphones when I’m alone really."]]},"do you like looking at yourself in the mirror?":{"blocks":[["A","I am not sure whether I like it or not, but I do it every day before I go out of the house. "],["R","I need to check my face, my hair and make sure I am looking as presentable as possible before I head out to the office."]]},"have you ever bought mirrors?":{"blocks":[["A","Yes, I have often bought little mirrors to take in my handbag, "],["R","so I can check myself sporadically during the day. "],["X","Perhaps before a meeting or after lunch, or if I am going from work to a dinner or something like that."]]},"do you usually take a mirror with you?":{"blocks":[["A","Yes, I usually take a small mirror with me. "],["C","However, in more recent years, I don't use it. "],["E","I tend to use my mobile phone - many people do these days - you know, you put the camera on selfie mode, and then you can look at yourself just as if you are looking in a mirror."]]},"would you use mirrors to decorate your room?":{"blocks":[["A","I have never used mirrors to decorate my living space, but I think it's a good idea. "],["R","If you put mirrors in certain places in your house they can make it look bigger, or lighter or change the space in a positive way. "],["S","So, yes, I would use mirrors to decorate my room, certainly."]]},"what kinds of websites do you usually use?":{"blocks":[["A","I use a number of websites very regularly. "],["E","These are usually online shopping websites – two in particular. I buy a lot of things online – from clothes and shoes, to kitchen accessories and food and snacks."]]},"what is your favorite website?":{"blocks":[["A","My favourite website is one I do not use that often. "],["E","It's a website dedicated to trainers… to sneakers... you know, sporty shoes. "],["R","I love trainers."]]},"what kinds of websites are popular in your country?":{"blocks":[["A","Just like I mentioned, shopping websites. "],["S","These are most certainly the most popular websites in my country. "],["R","Everyone buys things online – it’s convenient, reliable and you can buy pretty much anything you need from several online companies."]]},"do you like morning or evening?":{"blocks":[["A","Personally, I prefer the morning than the evening. "],["R","The mornings are the times when I really can focus on my studies the best and my concentration is at its peak. That’s mainly because I am someone who sleeps early and wakes up early feeling very refreshed."]]},"what do you usually do in the evening?":{"blocks":[["A","In the evenings I like to relax, basically. "],["E","Just rest and listen to music on headphones, or watch a TV show or something like that. "],["C","I have friends who always study in the evenings."]]},"are there any differences between what you do in the evening now and what you did in the past?":{"blocks":[["A","Yes, most certainly. "],["C","When I was a bit younger I would have a much more active social life in the evenings, and I also used to try to study in bed at night too. Now, I have a much more organized life."]]},"have you ever seen some old buildings in your city?":{"blocks":[["A","Yes, I’ve visited quite a few old buildings. "],["R","I’m a big fan of history and so I enjoy going to the famous sights, but also when my family visit Chengdu to see us, I enjoy taking them to the most famous old examples of architecture and culture."]]},"do you think we should keep old buildings in cities?":{"blocks":[["A","We should always strive to preserve our history. "],["R","History is an important and meaningful part of a country’s culture and heritage and it’s important to renovate and preserve old buildings."]]},"do you prefer living in an old building or a modern house?":{"blocks":[["A","I’d prefer to live in an old building, which has been modernized inside! "],["E","So, I would like a bit of both! "],["R","I like the charm of old buildings, but the functionality of modern living!"]]},"do you wear a watch?":{"blocks":[["A","Yes, I wear a watch – I have a smart watch which I wear all the time. "],["E","I use the watch to set calendar reminders, send short messages, make quick calls and make notes, as well as monitor my health stats and daily steps."]]},"why do some people wear expensive watches?":{"blocks":[["R","Some people genuinely appreciate a fine, precision-made watch, and others enjoy the status symbol of having an expensive watch. "],["E","Some people care about both!"]],"note":"题目直接问“为什么”，这里列举的是两类原因，不是独立的观点、理由、例子三步。"},"do you think it is important to wear a watch? why?":{"blocks":[["A","Well, not really essential these days "],["R","since everyone has a phone. "],["C","But I do think watches are still nice to have — "],["R","they look stylish and save you from constantly pulling out your phone. "],["E","Some people also wear them as a fashion statement."]]},"do you like singing?":{"blocks":[["A","I love singing. "],["E","I thoroughly enjoy going to KTVs and singing on my own at home to music, too."]]},"have you ever learnt how to sing?":{"blocks":[["A","No, not really. "],["E","To be honest, I’m not very good at singing – I think I might be tone deaf, even. "],["X","In school plays and performances I was never chosen to be one of the leading singers, and in KTV with friends, I usually try to keep a low profile and mouth the words – I really can’t sing well."]]},"if you sing, who would you sing in front of?":{"blocks":[["A","I wouldn’t want to sing for anyone – "],["R","I’d be way too embarrassed and self-conscious. As I said, I’m a terrible singer! "],["S","I would find it uncomfortable, so no, I would not sing for, or in front of anyone, if I could avoid it."]]},"do you think singing can bring happiness to people?":{"blocks":[["A","I understand that singing, if you’re good enough at it, can make people feel very happy. "],["E","The person singing as well as those listening. "],["R","Singing is a great form of musical expression, and there’s nothing more lovely than the human voice."]]},"have you ever learnt about outer space and stars?":{"blocks":[["A","Yes, in school we learnt the basic things about space and the solar system. "],["E","Also, I’ve seen a number of documentaries about the universe on television. I find the topic quite inspiring."]]},"are you interested in films about outer space and stars":{"blocks":[["A","Yes, I’d say so, yes. "],["E","I enjoy sci-fi films, although I don’t think there are many really good ones. I also have seen a few TV series set in space which I’ve enjoyed."]]},"do you want to go into outer space in the future?":{"blocks":[["A","Haha, no I don’t think so. "],["B","I’ve heard that some millionaires have actually signed up to go into the lower regions of space in space crafts, or orbit the earth, but I don’t really have much of a fascination with this. "],["R","To be honest, I think I’d be scared!"]]},"do you want to know more about outer space?":{"blocks":[["A","Absolutely, I'm fascinated by outer space! "],["R","The vastness, the mysteries it holds, and the potential for undiscovered planets and life forms spark my curiosity. "],["E","Each new discovery about outer space feels like a piece of a cosmic puzzle being placed, and I'm eager to see the picture it will eventually reveal."]]},"do you remember your teachers from primary school?":{"blocks":[["A","Yes, I remember most of them quite well. "],["E","I remember the ones I really liked, and I also remember the ones I really disliked! The motivating, humorous and inspiring teachers, as well as the strict, serious and critical teachers!"]]},"do you have a favorite teacher?":{"blocks":[["A","Yes, it was my mathematics teacher. "],["R","She was really good at making the subject interesting and she always gave real-life examples, and not just boring repetition drills, so I found I remembered what we learned in class much easier."]]},"did you want to be a teacher when you were younger?":{"blocks":[["A","I didn't really, no. "],["E","I didn't really think about it, actually. I always had aspirations to go into business or the medical field."]]},"what kinds of teacher do you prefer?":{"blocks":[["A","I prefer teachers that seem to be very sincere and ‘human' – you know, the kinds of teachers that make a subject really seem inspiring and worth learning about. "],["R","A good teacher, who has a sense of humour and the ability to inspire interest, can change your whole attitude to school!"]]},"are you still in touch with your primary school teachers?":{"blocks":[["A","Not really, to be honest. "],["E","I've lost touch with most of them over the years. "],["C","I do follow one or two on social media, but we don't really chat."]]},"in what way has your favourite teacher helped you?":{"blocks":[["A","Well, my favourite teacher was really encouraging. "],["X","Whenever I felt like giving up, she'd remind me that making mistakes is part of learning. "],["E","That really stuck with me."]]},"do you think you are an ambitious person?":{"blocks":[["A","That's a good question….Actually, I don't think I am that ambitious really. "],["E","Usually in life I choose to do things which I find to be predominantly stable and secure, rather than especially ambitious or adventurous things – you know, when it comes to career and work choices as well."]]},"what was your dream when you were a child?":{"blocks":[["A","When I was a child I had simple and accessible dreams I'd say – I wanted to be a teacher. "],["R","I loved the idea of teaching children and sharing my thoughts and experiences in life with them. "],["S","I always had this dream as a youngster."]]},"what is your main ambition in life now?":{"blocks":[["A","My main ambition in life, to be honest, is to maintain a stable, secure and simple happy life. "],["E","I don't want to do anything especially fancy or amazing really. "],["R","I enjoy the simple things in life, I'd say."]]},"are you the kind of person who never gives up on dreams?":{"blocks":[["A","I am the kind of person who persists, yes, at least with certain things. "],["R","Because I have realistic dreams I always feel they are obtainable, so I make sure I put the necessary effort into making them come true. "],["E","I rarely aim for things that I know I'm unable to attain."]]},"did you often go to the cinema when you were a child?":{"blocks":[["A","I didn’t really no. "],["E","I went occasionally with my sister, but not very often to be honest."]]},"do you often go to the cinema with your friends?":{"blocks":[["A","Nowadays I go to the cinema about once a month – "],["R","there’s a new cinema complex right near my home in a mall. "],["E","It’s a fantastic cinema and they have all the latest movies."]],"note":"影院位置是补充背景，也能说明去看电影方便；不要把破折号后的片段单独当成完整回应。"},"do you still like the same kind of movie which you liked when you were a child?":{"blocks":[["A","Pretty much. "],["E","I’ve always liked fun, romantic and lighthearted films. I still enjoy a lot of animations and cartoons too."]]},"what genres of films do you like?":{"blocks":[["A","I have a diverse taste in films; I enjoy genres like action, drama, and science fiction. "],["E","If I was to say which I really preferred, though, I would probably say action movies that are based around spy stories, secret agent thrillers and things like this – I prefer this genre than the superhero genre, most of the time. "],["R","I find these films truly gripping."]]},"do you think going to the cinema is a good way to spend time with friends?":{"blocks":[["A","Going to the cinema is an excellent way to spend quality time with friends, "],["R","discussing the movie afterward enhances the experience, especially if you go for a meal and a few drinks and have time and the mood to chat about it. "],["C","But this is only really fun if it’s a good film that you all enjoy."]]},"have you ever posted anything on social media?":{"blocks":[["A","Yeah, all the time! "],["E","I mostly post photos from trips or just random things I find funny. I use Instagram the most — it's a great way to share moments with friends."]]},"do you like science?":{"blocks":[["A","Yes, I really enjoy science "],["R","because it helps us understand the world around us. "],["E","Science has the ability to explain natural phenomena, drive technological advancements, and improve our quality of life. It's fascinating to see how scientific discoveries shape our understanding and future."]]},"when did you start to learn science?":{"blocks":[["A","I started learning about science in school in my first year. "],["E","We had basic science lessons, in which we learned a bit about biology mainly, and some physics."]]},"what is your favorite subject of science?":{"blocks":[["A","My favourite subject is physics now. "],["R","That's because I'm really interested in space and the universe and I'm particularly good at mathematics. "],["E","There's a lot of complex math in astrophysics and I find it that really exciting."]]},"what kinds of interesting things have you done with science?":{"blocks":[["A","I've participated in several interesting science-related activities, including conducting experiments in school labs and participating in science fairs. "],["X","One memorable project involved building a simple electric circuit, which sparked my interest in electronics and how devices work."]]},"do you like watching science tv programs?":{"blocks":[["A","Absolutely, I find science TV programs very engaging and informative. "],["X","Shows like \"Cosmos\" and \"Planet Earth\" not only provide deep insights into scientific topics but are also visually stunning and well-produced, making learning both fun and interesting."]]},"do chinese people often visit science museums?":{"blocks":[["A","Yes, visiting science museums is quite popular among Chinese people, especially families with children and school groups. "],["R","These museums are designed to be interactive and educational, making science accessible and interesting for everyone. "],["X","Large cities in China, such as Beijing and Shanghai, have well-known science museums that are frequently visited by both locals and tourists."]]},"did you like going to parks as a child?":{"blocks":[["A","Yeah, definitely! "],["X","I used to go to the park near my home almost every weekend with my parents. "],["E","We'd fly kites, have picnics, that kind of thing."]]},"do you still like going to parks now?":{"blocks":[["A","Yeah, I still do, though not as often. "],["R","You know, life gets busy. "],["C","But whenever I get the chance, I love just sitting on a bench, listening to the birds, maybe reading a book."]]},"would you like to see more parks in your city?":{"blocks":[["A","Oh, absolutely. "],["R","I think cities can feel really overwhelming sometimes, so having more green spaces would make a huge difference. "],["E","It gives people a place to relax, exercise, or just breathe some fresh air."]]},"are there any parks you want to go to in the future?":{"blocks":[["A","Well, I've actually heard a lot about Central Park in New York — it just looks incredible in photos and movies. "],["E","I'd love to go for a walk there someday and see it for myself. There's also a bamboo forest park in Japan I came across online that looks really peaceful and beautiful."]]},"would you prefer to play in a personal garden or public garden?":{"blocks":[["A","I'd probably go for a personal garden, honestly. "],["R","It's just more peaceful — no crowds, no noise. "],["E","You can do whatever you want without worrying about other people."]]},"how are the parks today different from those you visited as a kid?":{"blocks":[["A","I think they're much better now. "],["E","There are more facilities — like outdoor gyms, better playgrounds, cleaner paths. "],["C","When I was little, parks were pretty basic."]]},"what do you like to do when visiting a park?":{"blocks":[["A","I usually just take a slow walk and enjoy the fresh air. "],["E","Sometimes I'll bring a book and sit somewhere quiet. "],["C","If I'm with friends, we might throw a frisbee or just sit on the grass and chat."]]},"did you enjoy traveling by car when you were a kid?":{"blocks":[["A","Yeah, I loved it! "],["X","I'd sit by the window and watch everything go by. "],["E","My parents would play music and we'd chat the whole way."]]},"what types of cars do you like?":{"blocks":[["A","I'm not really a car person, but I do love SUVs — "],["R","they're spacious and comfortable. "],["A","I'm also into electric cars lately "],["R","because of all the cool tech features. "],["S","I guess I care more about comfort than looks, honestly."]]},"do you prefer to be a driver or a passenger?":{"blocks":[["A","Definitely a passenger. "],["R","I can just sit back, listen to music, or take a nap. "],["C","Driving requires full concentration the whole time, which is pretty tiring."]]},"what do you usually do when there is a traffic jam?":{"blocks":[["A","I usually put on some music or a podcast. "],["E","Sometimes I'll just scroll through my phone or daydream a bit. It's annoying, but I've kind of learned to just accept it and make the most of the time."]]},"do you think car colours are important?":{"blocks":[["A","Not hugely, but I think colour does reflect personality a bit. "],["X","Like, a red car gives off a very different vibe from a white one. "],["E","Personally, I'd go for dark blue or grey — "],["R","it just looks clean and timeless."]]},"will you buy an expensive car in the future?":{"blocks":[["A","Maybe, if I can afford it! "],["C","I wouldn't make it a top priority though. "],["R","I'd rather spend money on travel or experiences."]]},"do you like shopping?":{"blocks":[["A","Not really. "],["R","I find shopping a bit of a drag to be honest. "],["E","I don’t like going around stores and shops looking at clothes and things."]]},"how often do you go shopping?":{"blocks":[["A","About once every couple of weeks, I think. "],["C","Of course, to buy food, I will go to the supermarket or a market about once a week, but that's just to buy some essentials – but clothes shopping or shopping for pleasure, I don't do that often. "],["S","Yes, about once a fortnight, I'd say, on average."]]},"do you prefer online shopping or in-store shopping?":{"blocks":[["A","Honestly, I prefer online shopping most of the time. "],["R","It's just so convenient — you can browse and compare prices without leaving home. "],["C","But for things like clothes or shoes, I'd rather try them on in store first."]]},"have you ever returned anything you bought online?":{"blocks":[["A","Yeah, actually. "],["X","I once ordered a jacket and it looked completely different from the photos — the colour was way off. "],["E","So I had to send it back, which was kind of a hassle."]]},"do you like to keep things tidy?":{"blocks":[["A","Yeah, I'd say I'm a fairly tidy person. "],["R","I feel kind of uncomfortable when my space is messy — it actually makes it hard to focus. "],["E","So I try to clean up regularly, especially my desk."]]},"did you use to keep your room tidy as a child?":{"blocks":[["A","Honestly, not really! "],["E","My room was a total mess most of the time. "],["X","Clothes everywhere, toys on the floor — my mum would constantly tell me to clean up."]]},"how do you keep your work or study space tidy?":{"blocks":[["A","I try to do a quick tidy-up at the end of each day — just putting things back where they belong and clearing my desk. "],["E","I also have a rule: if I'm not using it, it goes away. It sounds simple but it really helps keep things from piling up."]]},"do you think that it is necessary to be tidy?":{"blocks":[["A","I'd say yes, to a reasonable degree. "],["R","A tidy space just helps you think more clearly and saves time looking for things. "],["C","But I don't think you need to be obsessive about it either."]]},"do you prefer sad or happy music?":{"blocks":[["A","Honestly, it depends on my mood. "],["C","When I'm relaxing or feeling a bit down, I actually enjoy sad, slow songs — "],["R","they're somehow comforting. "],["C","But when I'm working out or need some energy, I'll go for upbeat stuff."]]},"does happy music make you feel more excited?":{"blocks":[["A","Yeah, definitely! "],["E","You know, when an upbeat song comes on, I just naturally want to move. It's like the energy of the music gets into you without even trying."]]},"what kind of clothes do you often wear in daily life?":{"blocks":[["A","In my normal, everyday life, I usually wear jeans and a T-shirt, perhaps a skirt or a dress in summer. "],["C","It really depends. "],["S","But usually quite casual clothes – clean and presentable, but casual attire, normally."]]},"is there any difference between the clothes you wear on weekends and weekdays?":{"blocks":[["A","Perhaps there's a bit of a difference, yes. "],["C","During the week I tend to focus more on wearing conventional styles, "],["R","because I have to go to work and must look a bit smarter. "],["C","On weekends I tend to be more laid back and wear more casual clothes, perhaps even slightly more informal clothes."]]},"is there any color you dislike when buying clothes?":{"blocks":[["A","I don't really like yellow. "],["R","I don't think this colour suits me. "],["E","Also pastel shades don't really suit me, either."]]},"do you like wearing t-shirts?":{"blocks":[["A","I wear T-shirts very often, in fact. "],["E","Especially in summer when the weather is warm. "],["R","I enjoy the freedom of wearing a T-shirt and I have quite a few different ones with all sorts of designs on them in fact – from sporty-style T-shirts with the classic sports logos, to more amusing T-shirts with funky designs and patterns on them."]]},"do you spend a lot of time choosing clothes?":{"blocks":[["A","I usually spend about 10 to 15 minutes in the morning choosing my outfit for the day. "],["E","I like to pick something comfortable and suitable for the weather, ensuring that it also matches the day's activities."]]},"are you good at telling jokes?":{"blocks":[["A","Honestly, not really! "],["E","I always mess up the timing or forget the punchline halfway through. My friends usually end up laughing at me rather than the joke itself."]]},"do your friends like to tell jokes?":{"blocks":[["A","Yeah, I have one friend who's hilarious — he can make anyone laugh without even trying. "],["C","The rest of us are pretty average though. "],["E","We joke around a lot, but it's more just silly banter than actual proper jokes, you know."]]},"do you like to watch comedies?":{"blocks":[["A","Yeah, I love them! "],["R","After a long day, there's nothing better than putting on a funny show and just switching off. I don't have to think too hard and it always cheers me up."]]},"have you ever watched a live show?":{"blocks":[["A","Yeah, once! "],["X","A friend dragged me to a stand-up comedy show and I wasn't expecting much, but it was so funny. "],["E","Laughing along with a whole crowd feels completely different from watching at home."]]}};
  var ROLES = {
    A: {kind:'answer', label:'直接回应', tip:'回答题目具体问的事，Yes / No 和后面的完整回应放在一起。'},
    R: {kind:'reason', label:'理由', tip:'说明为什么这样想、这样选或这样做。because / since 可以是线索，仍要看句意。'},
    E: {kind:'explain', label:'解释展开', tip:'把意思说具体：补充表现、做法、细节或结果。'},
    X: {kind:'explain', label:'解释展开 · 举例', tip:'用经历或例子说清楚；列举具体内容不等于列举理由。'},
    C: {kind:'explain', label:'解释展开 · 条件或对比', tip:'补充不同情况、例外，或前后差别。'},
    B: {kind:'explain', label:'解释展开 · 背景', tip:'交代背景，帮助听者理解后面的回应。'},
    S: {kind:'closing', label:'回扣总结', tip:'收束前面的内容，回到题目。'}
  };
  function esc(value) {return String(value || '').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function key(q) {return String(q || '').replace(/\s+/g,' ').trim().toLowerCase();}
  function signals(text, code) {
    var safe=esc(text.trim());
    // Highlight discourse cues within already reviewed blocks; cues do not assign roles.
    var pattern=code==='R'?/\b(because(?: of)?|since|due to|that[’']s (?:mainly )?because|primarily due to|as this is|as it directly)\b/gi:/\b(to be honest|honestly|to be more specific|for example|for instance|I mean|in fact)\b/gi;
    return safe.replace(pattern,'<strong class="answerSignal">$1</strong>');
  }
  function find(question) {return DATA[key(question)] || null;}
  function render(question, item) {
    var entry=find(question); if(!entry || !item)return '';
    // A changed model must be reviewed again instead of displaying stale boundaries.
    if(entry.blocks.map(function(b){return b[1];}).join('')!==item.model)return '';
    var route=[];
    entry.blocks.forEach(function(b){var k=ROLES[b[0]].kind;if(route[route.length-1]!==k)route.push(k);});
    var routeLabels={answer:'直接回应',reason:'理由',explain:'解释展开',closing:'回扣总结'};
    var flow=route.map(function(k){return '<span class="answerFlowItem" data-role="'+k+'">'+routeLabels[k]+'</span>';}).join('<span class="answerFlowArrow" aria-hidden="true">→</span>');
    var chunks=(item.chunks||[]).filter(function(x,i,a){return x&&a.indexOf(x)===i;}).slice(0,8);
    return '<details class="questionSupport answerSteps"><summary>思路与示范回答</summary><div class="supportBody">'
      +'<div class="answerFlow" aria-label="这段回答的展开顺序">'+flow+'</div>'
      +'<p class="supportNote answerOrderNote">按这段回答的实际意思拆分，顺序可以变化；没有出现的部分不强行补齐。</p>'
      +(entry.note?'<p class="answerSourceNote">'+esc(entry.note)+'</p>':'')
      +'<ol class="answerStepList">'+entry.blocks.map(function(b){var r=ROLES[b[0]];return '<li class="answerStep" data-role="'+r.kind+'"><div class="answerStepHead"><b>'+r.label+'</b><span>'+r.tip+'</span></div><p lang="en">'+signals(b[1],b[0])+'</p></li>';}).join('')+'</ol>'
      +'<details class="answerCueGuide"><summary>怎样区分这几块内容？</summary><p>直接回应回答“是什么 / 有没有 / 选哪个”；理由回答“为什么”；解释展开回答“具体是什么样、怎么做、有哪些例子”。</p><p><b>to be honest</b> 常表达态度；<b>because / since</b> 可能引出理由；<b>to be more specific / I mean / for example</b> 常帮助展开。提示语只是线索：since 也可以表示时间，列举的也可能是理由，要结合句意判断。</p></details>'
      +(chunks.length?'<div class="supportChunks" aria-label="相关词伙">'+chunks.map(function(c){return '<span>'+esc(c)+'</span>';}).join('')+'</div>':'')
      +'<div class="sampleAnswer"><b>完整示范回答</b><p lang="en">'+esc(item.model)+'</p>'
      +(item.modelAudio?'<button class="play" data-a="'+esc(item.modelAudio)+'" aria-label="播放示范回答音频">▶</button>':'')+'</div></div></details>';
  }
  var style=document.createElement('style');
  style.textContent='.answerFlow{display:flex;align-items:center;flex-wrap:wrap;gap:6px}.answerFlowItem{padding:5px 8px;border:1px solid #dfd4e8;border-radius:7px;background:#f5f0f9;color:#66427f;font-size:12px;font-weight:700}.answerFlowArrow{color:#9a87aa}.answerOrderNote{margin:8px 0 12px;line-height:1.65}.answerStepList{list-style:none;margin:0;padding:0;counter-reset:answerstep}.answerStep{counter-increment:answerstep;margin:9px 0;padding:11px 12px;border:1px solid #e8e1ee;border-radius:9px;background:#fff}.answerStepHead{display:flex;flex-wrap:wrap;align-items:baseline;gap:5px 9px}.answerStepHead>b{font-size:12px;color:#795d96}.answerStepHead>b:before{content:counter(answerstep)". ";color:#927ca2}.answerStepHead>span{font-size:11px;color:#806c8e;line-height:1.6}.answerStep>p{font-size:13px;line-height:1.85;margin:7px 0 0;color:#493653;overflow-wrap:anywhere}.answerSignal{color:#795294;text-decoration:underline;text-decoration-color:#d5c5df;text-underline-offset:3px}.answerSourceNote{font-size:12px;line-height:1.7;background:#faf5ed;border:1px solid #eadfce;color:#795d39;border-radius:7px;padding:9px 11px}.answerCueGuide{margin:12px 0;padding:8px 10px;border:1px solid #e9e1ef;border-radius:8px;background:#fcfafd}.answerCueGuide>summary{font-size:12px;color:#795d96;cursor:pointer}.answerCueGuide>p{font-size:12px;line-height:1.8;color:#6a5578}.answerSteps .supportBody{min-width:0}@media(max-width:480px){.answerStep{padding:9px}.answerStepHead{display:block}.answerStepHead>span{display:block;margin-top:4px}}';
  document.head.appendChild(style);
  window.IELTSAnswerSteps={data:DATA,roles:ROLES,find:find,renderHtml:render};
  if(window.MODE==='browse' && typeof window.renderBrowse==='function')window.renderBrowse();
})();
